String buildStatusReport(Thread[] threads) {
    StringBuilder sb = new StringBuilder();
    for (Thread t : threads) sb.append(t.getName()).append("(prio=").append(t.getPriority()).append(",alive=").append(t.isAlive()).append(") ");
    return sb.toString();
}
